/** Insertion sort; O(n^2) worst-case time, O(1) extra space. */
import java.util.*;
public class InsertionSort {static void sort(int[]a){for(int i=1;i<a.length;i++){int value=a[i],j=i-1;while(j>=0&&a[j]>value){a[j+1]=a[j];j--;}a[j+1]=value;}}public static void main(String[]args){Scanner sc=new Scanner(System.in);System.out.print("Array size: ");int n=sc.nextInt();if(n<0){System.out.println("Invalid size");sc.close();return;}int[]a=new int[n];System.out.println("Enter elements:");for(int i=0;i<n;i++)a[i]=sc.nextInt();sort(a);System.out.println(Arrays.toString(a));sc.close();}}